mapper.select:
SELECT video_title, video_id
FROM Video
WHERE course_id = #{courseId}

SELECT video_title, video_id
FROM Video
WHERE user_id = #{userId}

mapper.update:
UPDATE Video
SET video_title = #{videoTitle}, video_description = #{videoDescription}
WHERE video_id = #{videoId};

mapper.select:
SELECT Video.video_path
FROM Video
WHERE video_file_name = #{videoFileName}

SELECT Video.file_url
FROM Video
WHERE file_name = #{fileName}

mapper.update:
UPDATE Video
SET video_score = #{videoScore}
WHERE video_id = #{videoId}
